const settle = (ms: number): Promise<void> => new Promise(resolve => setTimeout(resolve, ms));

const recorder = (client: WebSocket) => {
  const seen: Wire[] = [];
  client.on('message', raw => seen.push(JSON.parse(String(raw)) as Wire));
  const firstOf = (type: string): number => seen.findIndex(frame => frame.type === type);
  return {
    seen,
    firstOf,
    // Resolves with the frame once it arrives.
    wait: (type: string): Promise<Wire> =>
      new Promise(resolve => {
        const found = seen.find(frame => frame.type === type);
        if (found) {resolve(found); return;}
        client.on('message', raw => {
          const frame = JSON.parse(String(raw)) as Wire;
          if (frame.type === type) resolve(frame);
        });
      }),
  };
};
```
