      const exported = (await import('../types/sessionStore.js')) as Record<string, unknown>;
      const StoreCannotList = exported['StoreCannotList'];
      if (typeof StoreCannotList !== 'function') {
        throw new Error(`the exported StoreCannotList this ticket adds is ${String(StoreCannotList)}`);
      }
      const {store} = storeOver(async () => {
        throw new StoreCannotList('collection cannot list');
      });

      const {url} = await startEngine({sessionStore: store, history: {enabled: true}});
      const client = open(url);
      const wire = transcript(client);
      await wire.wait('connected');
      send(client, {type: 'list_conversations'});
      await settle(150);

      const failure = wire.seen.find(frame => frame.type === 'error');
      expect({answered: wire.seen.slice(1).map(frame => frame.type), code: failure?.code}).toEqual({
        answered: ['error'],
        code: 'UNSUPPORTED',
      });
    });

    it('answers a list asked mid-turn before that turn sends stream_end, without waiting on the lock', async () => {
      const held = deferred();
      const holding: ChatOrchestrator = {
        processMessage: async () => '',
        async *processMessageStream(): AsyncGenerator<MessageChunk> {
          yield {type: 'text', text: 'first'};
          await held.until;
          yield {type: 'text', text: 'rest'};
          yield {type: 'stop', stopReason: 'end_turn'};
        },
      };
      const {url} = await startEngine({
        sessionStore: new InMemorySessionStore(),
        history: {enabled: true},
        orchestrator: holding,
      });
      const client = open(url);
      const wire = transcript(client);
      await wire.wait('connected');
      send(client, {type: 'user_message', content: 'hold this'});
      await wire.wait('entry_delta');
      send(client, {type: 'list_conversations'});
      await settle(250);
      held.release();
      await wire.wait('stream_end');

      const answered = wire.firstOf('conversation_list');
      expect({
        answeredWhileHeld: answered !== -1 && answered < wire.firstOf('stream_end'),
        frames: wire.seen.map(frame => frame.type),
      }).toEqual({
        answeredWhileHeld: true,
        frames: [
          'connected',
          'entry_upsert',
          'entry_upsert',
          'entry_delta',
          'conversation_list',
          'entry_delta',
          'entry_commit',
          'stream_end',
        ],
      });
    });

    it('carries a client from a conversation_list row to that conversation over the resume path', async () => {
      const store = new InMemorySessionStore();
      const {url} = await startEngine({sessionStore: store, history: {enabled: true}, resume: {enabled: true}});

      const first = open(url);
      const firstWire = transcript(first);
      const firstConnected = await firstWire.wait('connected');
      send(first, {type: 'user_message', content: 'hello'});
      await firstWire.wait('stream_end');
      first.terminate();
      await settle(100);

      const second = open(url);
      const secondWire = transcript(second);
      await secondWire.wait('connected');
      send(second, {type: 'list_conversations'});
      const listed = await secondWire.wait('conversation_list');
      second.terminate();
      await settle(100);

      const conversationId = firstConnected.sessionId ?? '';
      const row = (listed.conversations ?? []).find(candidate => candidate.sessionId === conversationId);

      const third = open(`${url}?sessionId=${conversationId}`);
      const thirdWire = transcript(third);
      const rejoined = await thirdWire.wait('connected');
      await settle(100);

      expect({
        rowEntryCount: row?.entryCount,
        resumed: rejoined.resumed,
        entryCount: rejoined.entryCount,
        replay: thirdWire.seen
          .filter(frame => frame.type === 'entry_upsert')
          .map(frame => ({index: frame.index, role: frame.entry?.role, content: frame.entry?.content})),
      }).toEqual({
        rowEntryCount: 2,
        resumed: true,
        entryCount: 2,
        replay: [
          {index: 0, role: 'user', content: 'hello'},
          {index: 1, role: 'assistant', content: 'hi'},
        ],
      });
    });

    it('warns at startup when history is on without resume, and stays quiet when resume is on', async () => {
      const logged: Array<Record<string, unknown>> = [];
      setLogger({
        debug: quiet,
        info: quiet,
        error: quiet,
        warn: (category, message, fields) => void logged.push({category, message, ...fields}),
      });
      try {
        await startEngine({sessionStore: new InMemorySessionStore(), history: {enabled: true}});
        const warnedWithoutResume = logged.length;
        logged.length = 0;
        await startEngine({sessionStore: new InMemorySessionStore(), history: {enabled: true}, resume: {enabled: true}});
        const warnedWithResume = logged.length;
        expect({warnedWithoutResume: warnedWithoutResume > 0, warnedWithResume}).toEqual({
          warnedWithoutResume: true,
          warnedWithResume: 0,
        });
      } finally {
        setLogger(SILENT);
      }
    });
  });
});

